response.body:
{
  "status": true,
  "message": "Pay With Bank initiated successfully",
  "data": {
    "currency": "{{jsonPath request.body '$.currency'}}",
    "amount": "{{jsonPath request.body '$.amount'}}",
    "amount_expected": "{{jsonPath request.body '$.amount'}}",
    "fee": 25.0,
    "vat": 1.88,
    "reference": "{{jsonPath request.body '$.reference'}}",
    "payment_reference": "KPY-PWB-{{jsonPath request.body '$.reference'}}",
    "transaction_reference": "{{jsonPath request.body '$.reference'}}",
    "status": "processing",
    "bank_code": "{{val (jsonPath request.body '$.bank_code') default='058'}}",
    "authorization": {
      "redirect_url": "https://pay.korapay.com/eft/{{jsonPath request.body '$.reference'}}"
    },
    "customer": {
      "name": "{{val (jsonPath request.body '$.customer.name') default='PWB Customer'}}",
      "email": "{{val (jsonPath request.body '$.customer.email') default='pwb@kora.test'}}"
    }
  }
}

{
  "status": true,
  "message": "Payment authorized successfully",
  "data": {
    "status": "success",
    "reference": "{{val (jsonPath request.body '$.transaction_reference') default='PWB-DYN-001'}}",
    "transaction_reference": "{{val (jsonPath request.body '$.transaction_reference') default='PWB-DYN-001'}}"
  }
}

{
  "status": true,
  "message": "EFT charge initiated successfully",
  "data": {
    "reference": "{{jsonPath request.body '$.reference'}}",
    "payment_reference": "KPY-EFT-{{jsonPath request.body '$.reference'}}",
    "amount": "{{jsonPath request.body '$.amount'}}",
    "currency": "{{jsonPath request.body '$.currency'}}",
    "fee": 15.0,
    "vat": 1.13,
    "status": "processing",
    "authorization": {
      "redirect_url": "https://pay.korapay.com/eft/{{jsonPath request.body '$.reference'}}"
    },
    "customer": {
      "name": "{{val (jsonPath request.body '$.customer.name') default='EFT Customer'}}",
      "email": "{{val (jsonPath request.body '$.customer.email') default='eft@kora.test'}}"
    }
  }
}
